result_payload.content:
        candidates = ["%s://%s" % (url.scheme, url.netloc),
                      "%s://%s/" % (url.scheme, url.netloc),
                      uri,
                      "*"]

        for u in candidates:
            if u in self.config.linkcheck_request_headers:
                headers = dict(DEFAULT_REQUEST_HEADERS)
                headers.update(self.config.linkcheck_request_headers[u])
                return headers

        return {}

    def check_uri() -> Tuple[str, str, int]:
        # split off anchor
        if '#' in uri:
            req_url, anchor = uri.split('#', 1)
            for rex in self.anchors_ignore:
                if rex.match(anchor):
                    anchor = None
                    break
        else:
            req_url = uri
            anchor = None

        # handle non-ASCII URIs
        try:
            req_url.encode('ascii')
        except UnicodeError:
            req_url = encode_uri(req_url)

        # Get auth info, if any
        for pattern, auth_info in self.auth:
            if pattern.match(uri):
                break
        else:
            auth_info = None

        # update request headers for the URL
        kwargs['headers'] = get_request_headers()

        try:
            if anchor and self.config.linkcheck_anchors:
                # Read the whole document and see if #anchor exists
                response = requests.get(req_url, stream=True, config=self.config,
                                        auth=auth_info, **kwargs)
                response.raise_for_status()
                found = check_anchor(response, unquote(anchor))

                if not found:
                    raise Exception(__("Anchor '%s' not found") % anchor)
            else:
                try:
                    # try a HEAD request first, which should be easier on
                    # the server and the network
                    response = requests.head(req_url, allow_redirects=True,
                                             config=self.config, auth=auth_info,
                                             **kwargs)
                    response.raise_for_status()
                except (HTTPError, TooManyRedirects) as err:
                    if isinstance(err, HTTPError) and err.response.status_code == 429:
                        raise
                    # retry with GET request if that fails, some servers
                    # don't like HEAD requests.
                    response = requests.get(req_url, stream=True,
                                            config=self.config,
                                            auth=auth_info, **kwargs)
                    response.raise_for_status()
        except HTTPError as err:
            if err.response.status_code == 401:
                # We'll take "Unauthorized" as working.
                return 'working', ' - unauthorized', 0
            elif err.response.status_code == 429:
                next_check = self.limit_rate(err.response)
                if next_check is not None:
                    self.wqueue.put(CheckRequest(next_check, hyperlink), False)
                    return 'rate-limited', '', 0
                return 'broken', str(err), 0
            elif err.response.status_code == 503:
                # We'll take "Service Unavailable" as ignored.
                return 'ignored', str(err), 0
            else:
                return 'broken', str(err), 0
        except Exception as err:
            return 'broken', str(err), 0
        else:
            netloc = urlparse(req_url).netloc
            try:
                del self.rate_limits[netloc]
            except KeyError:
                pass
        if response.url.rstrip('/') == req_url.rstrip('/'):
            return 'working', '', 0
        else:
            new_url = response.url
            if anchor:
                new_url += '#' + anchor
            # history contains any redirects, get last
            if response.history:
                code = response.history[-1].status_code
                return 'redirected', new_url, code
            else:
                return 'redirected', new_url, 0

    def check(docname: str) -> Tuple[str, str, int]:
        # check for various conditions without bothering the network
        if len(uri) == 0 or uri.startswith(('#', 'mailto:', 'tel:')):
            return 'unchecked', '', 0
        elif not uri.startswith(('http:', 'https:')):
            if uri_re.match(uri):
                # non supported URI schemes (ex. ftp)
                return 'unchecked', '', 0
            else:
                srcdir = path.dirname(self.env.doc2path(docname))
                if path.exists(path.join(srcdir, uri)):
                    return 'working', '', 0
                else:
                    self._broken[uri] = ''
                    return 'broken', '', 0
        elif uri in self._good:
            return 'working', 'old', 0
        elif uri in self._broken:
            return 'broken', self._broken[uri], 0
        elif uri in self._redirected:
            return 'redirected', self._redirected[uri][0], self._redirected[uri][1]

        # need to actually check the URI
        for _ in range(self.config.linkcheck_retries):
            status, info, code = check_uri()
            if status != "broken":
                break

        if status == "working":
            self._good.add(uri)
        elif status == "broken":
            self._broken[uri] = info
        elif status == "redirected":
            self._redirected[uri] = (info, code)

        return (status, info, code)

    while True:
        check_request = self.wqueue.get()
        try:
            next_check, hyperlink = check_request
            if hyperlink is None:
                break

            uri, docname, lineno = hyperlink
        except ValueError:
            # old styled check_request (will be deprecated in Sphinx-5.0)
            next_check, uri, docname, lineno = check_request

        if uri is None:
            break
        netloc = urlparse(uri).netloc
        try:
            # Refresh rate limit.
            # When there are many links in the queue, workers are all stuck waiting
            # for responses, but the builder keeps queuing. Links in the queue may
            # have been queued before rate limits were discovered.
            next_check = self.rate_limits[netloc].next_check
        except KeyError:
            pass
        if next_check > time.time():
            # Sleep before putting message back in the queue to avoid
            # waking up other threads.
            time.sleep(QUEUE_POLL_SECS)
            self.wqueue.put(CheckRequest(next_check, hyperlink), False)
            self.wqueue.task_done()
            continue
        status, info, code = check(docname)
        if status == 'rate-limited':
            logger.info(darkgray('-rate limited-   ') + uri + darkgray(' | sleeping...'))
        else:
            self.rqueue.put(CheckResult(uri, docname, lineno, status, info, code))
        self.wqueue.task_done()

def limit_rate(self, response: Response) -> Optional[float]:
    next_check = None
    retry_after = response.headers.get("Retry-After")
    if retry_after:
        try:
            # Integer: time to wait before next attempt.
            delay = float(retry_after)
        except ValueError:
            try:
                # An HTTP-date: time of next attempt.
                until = parsedate_to_datetime(retry_after)
            except (TypeError, ValueError):
                # TypeError: Invalid date format.
                # ValueError: Invalid date, e.g. Oct 52th.
                pass
            else:
                next_check = datetime.timestamp(until)
                delay = (until - datetime.now(timezone.utc)).total_seconds()
        else:
            next_check = time.time() + delay
    netloc = urlparse(response.url).netloc
    if next_check is None:
        max_delay = self.config.linkcheck_rate_limit_timeout
        try:
            rate_limit = self.rate_limits[netloc]
        except KeyError:
            delay = DEFAULT_DELAY
        else:
            last_wait_time = rate_limit.delay
            delay = 2.0 * last_wait_time
            if delay > max_delay and last_wait_time < max_delay:
                delay = max_delay
